<script setup lang="ts">
import {computed,onBeforeUnmount,onMounted,ref,watch} from 'vue'
import {localFetch} from './http'
import {vRememberDisclosure} from './rememberDisclosure'
import {conditionalResearchUrl,conditionalResearchSha256} from './v6ConditionalResource'
import {validateResearch,visibleReplay,probabilityPlot,outcomeKnownAt,readPreferences,savePreferences} from './v6ConditionalResearch'
import type {ResearchData,Target,Probability} from './v6ConditionalResearch'

const props=defineProps<{payload?:ResearchData;initialOrigin?:string;initialStage?:number;initialRoot?:'M1'|'M2'}>()
const preferences=readPreferences()
const data=ref<ResearchData|null>(props.payload?validateResearch(props.payload):null),loading=ref(!props.payload),error=ref('')
const origin=ref(props.initialOrigin||preferences.origin||''),horizon=ref(preferences.horizon===2?2:3),stage=ref(props.initialStage??preferences.stage??0)
const direction=ref<'up'|'down'>(preferences.direction==='down'?'down':'up'),asOfOnly=ref(props.initialStage!=null||preferences.asOfOnly===true),reveal=ref(!asOfOnly.value),period=ref<'full'|'month'>('full'),calHorizon=ref(1)
const bridgeMode=ref(props.initialRoot?props.initialRoot==='M1':preferences.bridgeMode!==false)
const initialHorizon=ref([1,2,3].includes(preferences.initialHorizon||0)?preferences.initialHorizon!:1)
const controller=new AbortController()
const root=computed(()=>data.value?.roots[origin.value]||data.value?.roots[data.value.defaultOrigin])
const target=computed(()=>root.value?.targets.find(t=>t.horizon===horizon.value)||root.value?.targets.find(t=>t.horizon>=2))
const replay=computed(()=>root.value&&target.value?visibleReplay(root.value,target.value,asOfOnly.value?stage.value:999,bridgeMode.value?'M1':'M2'):null)
const showActual=computed(()=>!!(reveal.value&&replay.value?.outcomeKnown))
const plot=computed(()=>replay.value&&target.value?probabilityPlot(replay.value.points,target.value.updates.length+1,direction.value,showActual.value?{up:target.value.outcome.up,at:target.value.outcome.availableAt}:undefined):null)
const asOf=computed(()=>replay.value?.current.at||(root.value?.origin+'T08:30:00+08:00'))
const current=computed(()=>replay.value?.current.probabilities.R2)
const change=computed(()=>{const points=replay.value?.points||[];return points.length>1?100*(points.at(-1)!.probabilities.R2[direction.value]-points.at(-2)!.probabilities.R2[direction.value]):null})
const dates=computed(()=>data.value?.origins||[])
const selectedName=computed(()=>direction.value==='up'?'上漲':'下跌')
const calibration=computed(()=>data.value?.summary.calibration.filter(r=>r.family==='initial'&&r.group==='H'+calHorizon.value&&r.model==='M1')||[])
const calibrationStats=computed(()=>{const rows=calibration.value,n=rows.reduce((a,r)=>a+r.n,0);return {n,forecast:n?rows.reduce((a,r)=>a+r.n*(r.mean||0),0)/n:0,actual:n?rows.reduce((a,r)=>a+r.n*(r.actual||0),0)/n:0}})
const deltaStats=computed(()=>{if(!bridgeMode.value)return {first:data.value?.summary.deltas.mean_delta1||0,second:data.value?.summary.deltas.mean_delta2||0};const samples=Object.values(data.value?.roots||{}).flatMap(r=>r.targets.filter(t=>t.horizon===3&&t.updates.length===2));return {first:samples.reduce((a,t)=>a+t.updates[0]!.models.R2.up-t.initial.M1.up,0)/samples.length,second:samples.reduce((a,t)=>a+t.updates[1]!.models.R2.up-t.updates[0]!.models.R2.up,0)/samples.length}})
function revisionMetric(row:ResearchData['summary']['revision'][number],key:'R0'|'R1'|'R2'){
 if(key==='R0'&&bridgeMode.value){const h=row.case==='H2remaining1'?2:3;const initial=data.value!.summary.initial.find(r=>r.horizon===h)!;return (period.value==='full'?initial.models:initial.month).M1}
 return (period.value==='full'?row.models:row.month)[key]
}
const fmt=(n:number|null|undefined,d=1)=>n==null?'—':n.toLocaleString('zh-TW',{maximumFractionDigits:d,minimumFractionDigits:d})
const signed=(n:number,d=1)=>(n>0?'+':'')+fmt(n,d)
const timeLabel=(value:string)=>value.slice(0,16).replace('T',' ')
const pc=(p:Probability,key:'up'|'down')=>fmt(key==='up'?p.upPct:p.downPct)
const known=(t:Target)=>outcomeKnownAt(t,asOf.value)
const nameCase=(key:string)=>key==='H2remaining1'?'T+2事件 · 剩1日':key==='H3remaining2'?'T+3事件 · 剩2日':'T+3事件 · 剩1日'
function chooseOrigin(value:string){
 if(!data.value?.roots[value])return
 origin.value=value;stage.value=0;reveal.value=!asOfOnly.value
 if(!data.value.roots[value].targets.some(t=>t.horizon===horizon.value))horizon.value=data.value.roots[value].targets.find(t=>t.horizon>=2)?.horizon||3
}
function chooseHorizon(value:number){horizon.value=value;stage.value=0;reveal.value=!asOfOnly.value}
function chooseStage(value:number){asOfOnly.value=true;stage.value=value;reveal.value=replay.value?.current.kind==='outcome'}
function chooseAsOf(value:boolean){asOfOnly.value=value;stage.value=0;reveal.value=!value}
function initialize(){
 if(!data.value)return
 if(!data.value.roots[origin.value])origin.value=data.value.defaultOrigin
 if(!root.value?.targets.some(t=>t.horizon===horizon.value))horizon.value=root.value?.targets.find(t=>t.horizon>=2)?.horizon||3
 if(replay.value)stage.value=replay.value.index
}
initialize()
watch([origin,horizon,stage,direction,asOfOnly,initialHorizon,bridgeMode],()=>savePreferences({origin:origin.value,horizon:horizon.value,stage:stage.value,direction:direction.value,asOfOnly:asOfOnly.value,initialHorizon:initialHorizon.value,bridgeMode:bridgeMode.value}))
async function load(){
 loading.value=true;error.value=''
 try{
  const response=await localFetch(conditionalResearchUrl,{signal:controller.signal})
  if(!response.ok)throw Error('研究資料尚未部署，正式監控仍可使用。')
  const raw=await response.text()
  if(globalThis.crypto?.subtle){
   const hash=await crypto.subtle.digest('SHA-256',new TextEncoder().encode(raw))
   const hex=Array.from(new Uint8Array(hash),v=>v.toString(16).padStart(2,'0')).join('')
   if(hex!==conditionalResearchSha256)throw Error('研究資料與封存版本不符，暫不顯示。')
  }
  data.value=validateResearch(JSON.parse(raw));initialize()
 }catch(e){if((e as Error).name!=='AbortError')error.value=(e as Error).message}
 finally{loading.value=false}
}
onMounted(()=>{if(!props.payload)load()})
onBeforeUnmount(()=>controller.abort())
</script>

<template>
 <section class="conditional-research" aria-label="盤前條件預報研究回放">
  <header class="research-heading"><div><div class="eyebrow">CONDITIONAL FORECAST · RESEARCH REPLAY</div><h2>盤前條件預報研究</h2><p>把夜盤訊息放進機率，並追蹤同一個到期日的修訂。</p></div><span class="research-badge">歷史重建 · 尚未啟用</span></header>
  <p v-if="loading" class="status" role="status">正在讀取封存研究資料…</p>
  <div v-else-if="error" class="status error" role="alert"><p>{{error}}</p><button @click="load">重新讀取研究資料</button></div>
  <template v-else-if="data&&root">
   <div class="research-basis"><span>資料截至 <b>{{data.dataCutoff}}</b></span><span>{{data.indexLabel}} · 對原起點收盤漲跌</span><span>{{data.calculatedOn}}重建，非當日發布紀錄</span></div>
   <details v-remember-disclosure="'v6.conditional.adoption.v2'" class="adoption-notes"><summary>研究版本與接入條件</summary><div class="adoption-grid">
    <article><span class="small-label">初始預報候選</span><b>M1 · 夜盤＋波動</b><p>三個期限通過歷史比較；實際前瞻進度見本頁上方。</p></article>
    <article class="revision-gate"><span class="small-label">修訂研究候選</span><b>R2 · 加入新資訊</b><p>比較通過，但原M2起點未通過升級，尚未驗證改接M1。</p></article>
    <article><span class="small-label">正式接入資格</span><b>見上方前瞻觀察</b><p>本區是歷史快照；實際成熟筆數與接入條件列在本頁上方，不將回測計入。</p></article>
   </div></details>

   <section class="replay-card" aria-label="固定原起點的歷史機率回放">
    <div class="replay-heading"><div><span class="small-label">選擇回測起點</span><h3>舊08:30夜盤模型 · 歷史回放</h3></div><div class="origin-control"><label for="conditional-origin">起點日期</label><select id="conditional-origin" :value="root.origin" @change="chooseOrigin(($event.target as HTMLSelectElement).value)"><option v-for="d in dates" :key="d" :value="d">{{d}}</option></select><button class="example" @click="chooseOrigin('2026-10-06')">看10/6範例</button></div></div>
    <p class="anchor">原起點 {{root.anchorDate}} 收盤 <strong>{{fmt(root.anchorClose,2)}} 點</strong><span>上漲含恰好收平；沒有平盤類別。</span></p>
    <div class="answer-controls"><div role="group" aria-label="夜盤模型預報期限"><button v-for="h in [1,2,3]" :key="h" :aria-pressed="initialHorizon===h" @click="initialHorizon=h;h>=2&&chooseHorizon(h)">T+{{h}}</button></div><span>歷史範例 · 非今日預報</span></div>
    <div class="initial-grid single-answer">
     <article v-for="h in [1,2,3]" :key="h" v-show="initialHorizon===h" :data-horizon="h" data-scope="initial-M1">
      <template v-for="t in root.targets.filter(t=>t.horizon===h)" :key="t.horizon">
       <div class="target-title"><b>T+{{h}}</b><span>{{t.targetDate}} 收盤</span></div><small>夜盤模型 · 起點機率</small>
       <div class="two-prob"><div class="up"><span>上漲</span><strong>{{pc(t.initial.M1,'up')}}<em>%</em></strong></div><div class="down"><span>下跌</span><strong>{{pc(t.initial.M1,'down')}}<em>%</em></strong></div></div>
       <div class="prob-bar" aria-hidden="true"><span class="up-fill" :style="{width:t.initial.M1.up*100+'%'}"></span><span class="down-fill" :style="{width:t.initial.M1.down*100+'%'}"></span></div>
       <p v-if="reveal&&known(t)" class="realized">當時已知結果：{{t.outcome.up?'上漲（含收平）':'下跌'}} {{signed(t.outcome.returnPct,2)}}%</p><p v-else class="outcome-hidden">{{known(t)?'結果可核對，尚未展開':'此回放時點尚未到期'}}</p>
      </template>
      <template v-if="!root.targets.some(t=>t.horizon===h)"><div class="target-title"><b>T+{{h}}</b><span>本輪無樣本</span></div><p class="missing-target">封存時尚未到期，未納入本輪樣本；不補造機率。</p></template>
     </article>
    </div>
    <p class="input-caption">起點已知：同合約夜盤 {{signed(root.inputs.nightReturnPct,2)}}% · 現貨EWMA日波動 {{fmt(root.inputs.dailySigmaPct,2)}}%<span>這是所選歷史起點的預報，不隨研究圖改寫；今日實際進度見頁面上方。</span></p>

    <details v-remember-disclosure="'v6.conditional.legacy.v2'" class="legacy-revision"><summary>機率修訂路徑 · 重算研究</summary>
    <div class="revision-heading"><div><span class="small-label">{{bridgeMode?'夜盤模型接續修訂 · 新研究版本':'原M2事件的修訂研究'}}</span><h3>機率怎麼隨新資訊改變</h3></div><span class="blocked">{{bridgeMode?'新接續研究 · 未接入':'未接入 · 原M2資格未通過'}}</span></div>
    <p class="separate-roots" v-if="bridgeMode">起點與上方夜盤模型相同；後續沿用已封存的修訂算法，重算輸出不變。這是已開啟歷史的銜接研究，尚未驗證正式接入，未計入0／60。</p><p v-else class="separate-roots">此圖沿用原M2起點；與上方M1卡片分開，不能當成已驗證的M1＋R2組合。</p>
    <div v-if="target&&replay&&plot" class="revision-content">
     <label class="bridge-mode"><input v-model="bridgeMode" type="checkbox">以夜盤模型為起點（重算研究）<small>取消可查看封存舊起點。</small></label>
     <label class="asof-mode"><input type="checkbox" :checked="asOfOnly" @change="chooseAsOf(($event.target as HTMLInputElement).checked)">只看當時資訊 <span>關閉時顯示已到期事件的完整歷史路徑。</span></label>
     <div class="revision-controls"><div class="horizon-buttons" role="group" aria-label="修訂事件期限"><button v-for="h in [2,3]" :key="h" :disabled="!root.targets.some(t=>t.horizon===h)" :aria-pressed="target.horizon===h" @click="chooseHorizon(h)">T+{{h}}事件</button></div><strong class="fixed-deadline">固定到期 {{target.targetDate}}</strong><label class="direction-label">曲線方向<select v-model="direction"><option value="up">上漲機率</option><option value="down">下跌機率</option></select></label></div>
     <div class="time-steps" role="group" aria-label="選擇當時資訊時點"><button v-for="(step,i) in replay.steps" :key="step.at" :class="{active:i===replay.index}" :aria-pressed="i===replay.index" @click="chooseStage(i)"><span>{{step.label}}</span><b>{{step.at.slice(5,10)}} {{step.at.slice(11,16)}}</b></button></div>
     <div class="asof"><span>目前只看到 <b>{{timeLabel(replay.current.at)}}</b> 的資訊</span><div><button :disabled="replay.index===0" @click="chooseStage(replay.index-1)" aria-label="前一個資訊時點">← 前一時點</button><button :disabled="replay.index===replay.steps.length-1" @click="chooseStage(replay.index+1)" aria-label="下一個資訊時點">下一時點 →</button></div></div>
     <div class="chart-grid">
      <div class="plot-wrap"><div class="chart-label">{{selectedName}}機率 · 相對固定原起點</div><svg :viewBox="`0 0 ${plot.width} ${plot.height}`" role="img" :aria-label="`原M2事件的${selectedName}機率修訂圖，階梯圖；預報與實際結果分開標示`">
       <g v-for="p in [0,.5,1]" :key="p"><line :x1="plot.left" :x2="plot.right" :y1="plot.y(p)" :y2="plot.y(p)" :class="{middle:p===.5}"/><text :x="plot.left-12" :y="plot.y(p)+4" text-anchor="end">{{p*100}}%</text></g>
       <g v-for="(step,i) in replay.steps.filter(s=>s.kind!=='outcome')" :key="step.at" class="date-label"><text :x="plot.x(i)" y="270" text-anchor="middle">{{step.at.slice(5,10)}}</text><text :x="plot.x(i)" y="300" text-anchor="middle">{{i===0?'原預報':'修訂'+i}}</text></g>
       <g v-for="line in plot.lines" :key="line.key" :class="'series '+line.key"><path :d="line.path" fill="none"/><g v-for="point in line.points" :key="point.at"><circle :cx="point.x" :cy="point.y" :r="line.key==='R2'?5.5:3.5"><title>{{timeLabel(point.at)}} · {{line.key}} {{pc(point.p,direction)}}%</title></circle><text v-if="line.key==='R2'" class="point-probability" :x="point.x" :y="point.y<55?point.y+23:point.y-13" text-anchor="middle">{{pc(point.p,direction)}}%</text></g></g>
       <g v-if="plot.actual" class="actual-endpoint"><path :d="`M${plot.lines[2]!.points.at(-1)!.x},${plot.lines[2]!.points.at(-1)!.y} H${plot.actual.x} V${plot.actual.y}`" class="outcome-link"/><path :d="`M${plot.actual.x},${plot.actual.y-7} l7,7 -7,7 -7,-7 Z`"/><text :x="plot.actual.x-8" :y="plot.actual.y<55?plot.actual.y+25:plot.actual.y-14" text-anchor="end">實際 {{plot.actual.pct}}%</text><text :x="plot.actual.x" y="270" text-anchor="end">{{plot.actual.at.slice(5,10)}}</text><text :x="plot.actual.x" y="300" text-anchor="end">13:30結果</text></g>
      </svg><div class="legend"><span class="R0">起點不變</span><span class="R1">僅更新已實現價格</span><span class="R2">新資訊修訂</span></div></div>
      <aside class="current-point"><span class="small-label">{{replay.current.kind==='initial'?(bridgeMode?'夜盤模型起點預報':'舊版起點預報'):'新資訊修訂（歷史研究）'}}</span><div class="large-prob">{{current?pc(current,direction):'—'}}<small>%</small></div><b>{{selectedName}} · {{timeLabel(replay.points.at(-1)!.at)}}</b><p v-if="change!=null">較前次 <strong>{{signed(change)}}百分點</strong></p><p v-else>最初值，尚未修訂。</p><p class="opposite">{{direction==='up'?'下跌':'上漲'}} {{current?pc(current,direction==='up'?'down':'up'):'—'}}%</p><p v-if="replay.current.kind==='outcome'" class="at-deadline">此處保留最後一次預報；圖末菱形的0%／100%是實際結果。</p></aside>
     </div>
     <div class="visible-history" tabindex="0" aria-label="當時可見的修訂數值"><table><thead><tr><th>當時資訊</th><th>{{bridgeMode?'夜盤模型起點':'原M2'}}</th><th>已實現價格修訂</th><th>新資訊修訂</th><th>較前次</th></tr></thead><tbody><tr v-for="(point,i) in replay.points" :key="point.at"><td>{{point.at.slice(0,10)}}<small>08:30 · {{point.label}}</small></td><td>{{pc(point.probabilities.R0,direction)}}%</td><td>{{pc(point.probabilities.R1,direction)}}%</td><td><b>{{pc(point.probabilities.R2,direction)}}%</b></td><td>{{i?signed(100*(point.probabilities.R2[direction]-replay.points[i-1]!.probabilities.R2[direction]))+'百分點':'最初值'}}</td></tr></tbody></table></div>
     <label class="outcome-toggle"><input v-model="reveal" type="checkbox">顯示當時已知的到期結果</label><p v-if="reveal&&replay.outcomeKnown" class="outcome-result" role="status">{{target.targetDate}} 原事件結果：<b>{{target.outcome.up?'上漲（含收平）':'下跌'}} {{signed(target.outcome.returnPct,2)}}%</b> · 收盤 {{fmt(target.outcome.close,2)}} 點</p><p v-else-if="reveal" class="subtle">當時尚未知道這個到期日的收盤，繼續保留空白。</p>
    </div><p v-else class="empty">這個起點只有T+1封存機率，沒有可回放的修訂樣本。</p></details>
   </section>

   <details v-remember-disclosure="'v6.conditional.evidence'" class="evidence-card"><summary><span class="small-label">整段研究結果 · 不隨回放時點改變</span><h3>多加資訊，是否真的更準？</h3></summary>
    <div class="evidence-body"><div class="period-select" role="group" aria-label="研究統計期間"><button :aria-pressed="period==='full'" @click="period='full'">完整測試期</button><button :aria-pressed="period==='month'" @click="period='month'">固定近一個月</button><span>{{(period==='full'?data.testPeriod:data.monthPeriod).join(' ～ ')}}</span></div>
     <p class="subtle">每格上行為Brier，下行為log loss，兩者越低越好；不是下跌機率或交易勝率。採用只按完整測試與全部既定門檻。</p>
     <div class="table-scroll" tabindex="0" aria-label="三個初始模型的機率誤差比較"><table><thead><tr><th>期限／筆數</th><th>M0 歷史比例</th><th>M1 夜盤＋波動</th><th>M2 再加海外</th><th>完整測試採用</th></tr></thead><tbody><tr v-for="row in data.summary.initial" :key="row.horizon"><td>T+{{row.horizon}}<small>{{(period==='full'?row.models:row.month).M1.n}}筆</small></td><td>{{fmt((period==='full'?row.models:row.month).M0.brier,4)}}<small class="log-loss">log loss {{fmt((period==='full'?row.models:row.month).M0.logLoss,4)}}</small></td><td class="selected-metric"><b>{{fmt((period==='full'?row.models:row.month).M1.brier,4)}}</b><small class="log-loss">log loss {{fmt((period==='full'?row.models:row.month).M1.logLoss,4)}}</small><small v-if="period==='full'">較M0減少{{fmt(row.improvement*100)}}%</small></td><td>{{fmt((period==='full'?row.models:row.month).M2.brier,4)}}<small class="log-loss">log loss {{fmt((period==='full'?row.models:row.month).M2.logLoss,4)}}</small></td><td><span class="candidate-badge">M1 候選</span></td></tr></tbody></table></div>
     <p class="finding">初始三個期限皆選M1。M2未再優於M1；近月T+2／T+3的M1也幾乎沒有降低誤差。</p>
     <div class="table-scroll" tabindex="0" aria-label="三個修訂方式的誤差比較"><table><thead><tr><th>原事件／剩餘</th><th>{{bridgeMode?'夜盤模型不修訂':'R0 不修訂'}}</th><th>R1 機械</th><th>R2 新資訊</th><th>接入狀態</th></tr></thead><tbody><tr v-for="row in data.summary.revision" :key="row.case"><td>{{nameCase(row.case)}}<small>{{(period==='full'?row.models:row.month).R2.n}}筆</small></td><td>{{fmt(revisionMetric(row,'R0').brier,4)}}<small class="log-loss">log loss {{fmt(revisionMetric(row,'R0').logLoss,4)}}</small></td><td>{{fmt(revisionMetric(row,'R1').brier,4)}}<small class="log-loss">log loss {{fmt(revisionMetric(row,'R1').logLoss,4)}}</small></td><td class="selected-metric"><b>{{fmt(revisionMetric(row,'R2').brier,4)}}</b><small class="log-loss">log loss {{fmt(revisionMetric(row,'R2').logLoss,4)}}</small><small v-if="period==='full'">較R1減少{{fmt(row.improvement*100)}}%</small></td><td>{{bridgeMode?'新接續尚未採用':'原M2資格未過'}}<small>仍為歷史研究</small></td></tr></tbody></table></div>
     <div class="limitations"><p>封存舊版R2比較通過，新接續僅為重算研究；不等於已驗證M1＋R2。晚期修訂已知道部分價格，也不能把其命中率當成提前三日能力。</p><p>兩次修訂平均{{signed(deltaStats.first*100,2)}}／{{signed(deltaStats.second*100,2)}}百分點，存在向下偏移。近期也有log loss未改善的階段，機率仍有校準偏差。</p></div>
    </div>
   </details>

   <details v-remember-disclosure="'v6.conditional.calibration'" class="calibration-card"><summary><span class="small-label">機率校準 · 完整測試期</span><h3>說有幾成，實際有幾成？</h3></summary><div class="calibration-body"><label>夜盤模型期限 <select v-model.number="calHorizon"><option :value="1">T+1</option><option :value="2">T+2</option><option :value="3">T+3</option></select></label><p class="calibration-summary">平均預報 <b>{{fmt(calibrationStats.forecast*100,2)}}%</b>，實際上漲 <b>{{fmt(calibrationStats.actual*100,2)}}%</b>；差 {{signed((calibrationStats.forecast-calibrationStats.actual)*100,2)}} 個百分點 · {{calibrationStats.n}}筆</p><p class="subtle">斜線表示預報與實際比例相同；偏離斜線表示有校準偏差。小於30筆的格子以空心標示，不能宣稱準確。</p><div class="calibration-grid"><svg viewBox="0 0 340 290" role="img" aria-label="M1預報機率對照實際上漲比例校準圖"><line x1="48" y1="238" x2="305" y2="238"/><line x1="48" y1="238" x2="48" y2="22"/><path d="M48,238 L305,22" class="ideal"/><g v-for="p in [0,.5,1]" :key="p"><text :x="48+257*p" y="258" text-anchor="middle">{{p*100}}%</text><text x="38" :y="242-216*p" text-anchor="end">{{p*100}}%</text></g><g v-for="point in calibration.filter(p=>p.n&&p.mean!=null&&p.actual!=null)" :key="point.low"><circle :cx="48+257*point.mean!" :cy="238-216*point.actual!" :r="Math.min(12,4+Math.sqrt(point.n)/2)" :class="{small:!point.enough}"><title>平均預報{{fmt(point.mean!*100)}}% · 實際{{fmt(point.actual!*100)}}% · {{point.n}}筆</title></circle></g><text x="180" y="283" text-anchor="middle">平均預報上漲機率</text><text x="48" y="12">實際上漲比例</text></svg><div class="table-scroll"><table><thead><tr><th>預報區間</th><th>平均預報</th><th>實際上漲</th><th>樣本</th></tr></thead><tbody><tr v-for="point in calibration" :key="point.low"><td>{{point.low*100}}～{{point.high*100}}%</td><td>{{point.mean==null?'—':fmt(point.mean*100)+'%'}}</td><td>{{point.actual==null?'—':fmt(point.actual*100)+'%'}}</td><td>{{point.n}}<small v-if="point.n&&!point.enough">樣本不足30</small></td></tr></tbody></table></div></div></div></details>
   <details v-remember-disclosure="'v6.conditional.method'" class="method-card"><summary>研究範圍、採用規則與資料版本</summary><div><p>研究代號：M0歷史比例、M1夜盤模型（M1起點機率）、M2加入海外因子的舊起點；R0不修訂、R1已實現價格修訂、R2新資訊修訂。資料是現貨加權指數，收平歸上漲。初始模型預測二分類機率，沒有產生新的目標價或80%價格區間。</p><p>規則：至少1%相對Brier改善、固定5／10／20日區塊區間上界小於0、各9項家族Holm p小於0.025、log loss不劣，以及資料與樣本資格。{{data.summary.passedComparisons}}／{{data.summary.formalComparisons}}項比較通過，不等於可上線的策略數。</p><p>歷史資料使用重建的08:30可用時間，並非當年保存的原始發布版本。這輪結果是回溯研究，不能當成全新盲測。頁面只讀封存資料，不抓新行情、不訓練、不保存模型決策。</p><p>方法 {{data.methodVersion}} · 研究版製作 {{timeLabel(data.generatedAt)}}</p></div></details>
  </template>
 </section>
</template>

